        vy: f32,
        /// Z velocity in NED frame
        vz: f32,
        /// X acceleration or force (if bit 10 of type_mask is set) in NED frame in meter / s^2 or N
        afx: f32,
        /// Y acceleration or force (if bit 10 of type_mask is set) in NED frame in meter / s^2 or N
        afy: f32,
        /// Z acceleration or force (if bit 10 of type_mask is set) in NED frame in meter / s^2 or N
        afz: f32,
        /// yaw setpoint
        yaw: f32,
        /// yaw rate setpoint
        yaw_rate: f32,
        /// Bitmap to indicate which dimensions should be ignored by the vehicle.
        type_mask: enums.POSITION_TARGET_TYPEMASK,
        /// System ID
        target_system: u8,
        /// Component ID
        target_component: u8,
        /// Valid options are: MAV_FRAME_LOCAL_NED = 1, MAV_FRAME_LOCAL_OFFSET_NED = 7, MAV_FRAME_BODY_NED = 8, MAV_FRAME_BODY_OFFSET_NED = 9
        coordinate_frame: enums.MAV_FRAME,
    };
    /// Status of geo-fencing. Sent in extended status stream when fencing enabled.
    pub const FENCE_STATUS = struct {
        /// Time (since boot) of last breach.
        breach_time: u32,
        /// Number of fence breaches.
        breach_count: u16,
        /// Breach status (0 if currently inside fence, 1 if outside).
        breach_status: u8,
        /// Last breach type.
        breach_type: enums.FENCE_BREACH,

        // Extensions
        /// Active action to prevent fence breach
        breach_mitigation: enums.FENCE_MITIGATE = @fromBackingInt(0),
    };
    /// Information about video stream. It may be requested using MAV_CMD_REQUEST_MESSAGE, where param2 indicates the video stream id: 0 for all streams, 1 for first, 2 for second, etc.
    pub const VIDEO_STREAM_INFORMATION = struct {
        /// Video stream URI (TCP or RTSP URI ground station should connect to) or port number (UDP port ground station should listen to).
        uri: [160]i8,
        /// Stream name.
        name: [32]i8,
        /// Frame rate.
        framerate: f32,
        /// Bit rate.
        bitrate: u32,
        /// Bitmap of stream status flags.
        flags: enums.VIDEO_STREAM_STATUS_FLAGS,
        /// Horizontal resolution.
        resolution_h: u16,
        /// Vertical resolution.
        resolution_v: u16,
        /// Video image rotation clockwise.
        rotation: u16,
        /// Horizontal Field of view.
        hfov: u16,
        /// Video Stream ID (1 for first, 2 for second, etc.)
        stream_id: u8,
        /// Number of streams available.
        count: u8,
        /// Type of stream.
        type: enums.VIDEO_STREAM_TYPE,

        // Extensions
        /// Encoding of stream.
        encoding: enums.VIDEO_STREAM_ENCODING = @fromBackingInt(0),
        /// Camera id of a non-MAVLink camera attached to an autopilot (1-6).  0 if the component is a MAVLink camera (with its own component id).
        camera_device_id: u8 = 0,
    };
};
